-- Dashboard and reporting queries: aggregates, joins, subqueries
SELECT DATE(created_at) AS day, COUNT(*) AS orders, SUM(total) AS revenue FROM orders WHERE created_at >= NOW() - INTERVAL 30 DAY GROUP BY DATE(created_at) ORDER BY day;
SELECT YEAR(created_at) AS y, MONTH(created_at) AS m, SUM(total) FROM orders GROUP BY YEAR(created_at), MONTH(created_at) WITH ROLLUP;
SELECT DATE_FORMAT(created_at, '%Y-%m') AS ym, COUNT(DISTINCT customer_id) AS buyers FROM orders GROUP BY ym HAVING buyers > 10 ORDER BY ym DESC;
SELECT c.id, c.name, COUNT(o.id) AS n, COALESCE(SUM(o.total), 0) AS spent FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id, c.name ORDER BY spent DESC LIMIT 10;
SELECT product_id, SUM(qty) AS sold FROM order_items GROUP BY product_id ORDER BY sold DESC LIMIT 5;
SELECT category, GROUP_CONCAT(name ORDER BY name SEPARATOR ', ') AS names FROM products GROUP BY category;
SELECT user_id, GROUP_CONCAT(DISTINCT role) FROM user_roles GROUP BY user_id;
SELECT * FROM orders WHERE total > (SELECT AVG(total) FROM orders);
SELECT p.name, (SELECT COUNT(*) FROM reviews r WHERE r.product_id = p.id) AS review_count FROM products p;
SELECT * FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.total > 1000);
SELECT * FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);
SELECT t.day, t.cnt FROM (SELECT DATE(created_at) AS day, COUNT(*) AS cnt FROM visits GROUP BY DATE(created_at)) AS t WHERE t.cnt > 100;
SELECT status, COUNT(*) FROM orders GROUP BY status HAVING COUNT(*) > 5 ORDER BY COUNT(*) DESC;
SELECT CASE WHEN total < 50 THEN 'small' WHEN total < 500 THEN 'medium' ELSE 'large' END AS bucket, COUNT(*) FROM orders GROUP BY bucket;
SELECT SUM(IF(status = 'paid', total, 0)) AS paid, SUM(IF(status = 'refunded', total, 0)) AS refunded FROM orders;
SELECT IFNULL(region, 'unknown') AS region, COUNT(*) FROM customers GROUP BY region;
SELECT id, total, ROUND(total * 1.2, 2) AS gross FROM orders WHERE total BETWEEN 10 AND 100;
SELECT a.id FROM a UNION SELECT b.id FROM b UNION ALL SELECT c.id FROM c;
(SELECT id, 'order' AS kind FROM orders ORDER BY id DESC LIMIT 5) UNION ALL (SELECT id, 'refund' FROM refunds ORDER BY id DESC LIMIT 5);
SELECT DISTINCT country FROM customers WHERE country IS NOT NULL ORDER BY country;
SELECT TIMESTAMPDIFF(DAY, created_at, shipped_at) AS days_to_ship FROM orders WHERE shipped_at IS NOT NULL;
SELECT DATEDIFF(NOW(), last_login) AS idle FROM users HAVING idle > 90;
SELECT * FROM events WHERE ts >= DATE_SUB(NOW(), INTERVAL 1 HOUR);
SELECT * FROM events WHERE ts > NOW() - INTERVAL 15 MINUTE;
SELECT DATE_ADD(CURDATE(), INTERVAL 1 MONTH) AS next_month;
SELECT o.id, c.name, p.name FROM orders o JOIN customers c ON c.id = o.customer_id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id LEFT JOIN coupons cp ON cp.id = o.coupon_id WHERE o.status <> 'cancelled';
SELECT a.x FROM a NATURAL JOIN b;
SELECT * FROM a JOIN b USING (id) JOIN c USING (id);
SELECT * FROM t1 LEFT JOIN (t2, t3) ON t1.id = t2.id AND t2.id = t3.id;
SELECT * FROM a CROSS JOIN b;
SELECT * FROM a STRAIGHT_JOIN b ON a.id = b.id;
SELECT STRAIGHT_JOIN * FROM a, b WHERE a.id = b.id;
SELECT SQL_CALC_FOUND_ROWS * FROM posts LIMIT 10;
SELECT FOUND_ROWS();
SELECT * FROM users INTO OUTFILE '/tmp/users.csv';
